import React, { useState } from "react";

const Payment = () => {
  const [plan, setPlan] = useState("free");

  const handlePayment = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/payment/create-checkout-session", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ plan }),
      });

      const data = await res.json();
      if (data.url) {
        window.location.href = data.url; // chuyển sang cổng thanh toán (VD: Stripe, VNPay…)
      } else {
        alert("Thanh toán thất bại");
      }
    } catch (err) {
      console.error(err);
      alert("Có lỗi xảy ra!");
    }
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white shadow-lg rounded-2xl p-6 w-96 text-center">
        <h2 className="text-2xl font-bold mb-4">Chọn gói nâng cấp</h2>

        <div className="flex flex-col gap-2 mb-6">
          <label className="border p-3 rounded cursor-pointer">
            <input
              type="radio"
              name="plan"
              value="free"
              checked={plan === "free"}
              onChange={(e) => setPlan(e.target.value)}
            />{" "}
            Gói Miễn phí - 0đ
          </label>

          <label className="border p-3 rounded cursor-pointer">
            <input
              type="radio"
              name="plan"
              value="premium"
              checked={plan === "premium"}
              onChange={(e) => setPlan(e.target.value)}
            />{" "}
            Gói Premium - 199.000đ/tháng
          </label>
        </div>

        <button
          onClick={handlePayment}
          className="bg-blue-600 text-white py-2 px-4 rounded-lg hover:bg-blue-700 transition"
        >
          Thanh toán ngay
        </button>
      </div>
    </div>
  );
};

export default Payment;
